/**
 * Font: unique mapping of font type id → CSS font stack, and font size conversion. The settings page options are
 * generated by FONT_PRESETS, and the rendering layer is always evaluated by fontStackOf / resolveFontPx, without
 * writing literals separately. There is only id in the configuration but no font stack: If the font stack is rewritten
 * incorrectly, the style will be misspelled. id has a whitelist that can be verified. The host side also obtains the
 * list through this module: there is only one type of font, and the changes to both sides of the list will take effect
 * at the same time.
 * @module dsh-pet/src/shared/fonts
 */
import type { FontConfig, FontFamilyId } from './types.ts';

/** A font preset: id written into the configuration and CSS font stack shared by both ends. */
export interface FontPreset {
  id: FontFamilyId;
  /** The value of CSS font-family (excluding the trailing semicolon): the system font name is parallel across platforms fallback, and the last digit must be a universal family */
  stack: string;
}

/**
 * Font preset list: The order is the display order of the drop-down box on the setting page (the first item is the
 * default). candy is the only font released with the package. The name of CSS " ShangshouSoftCandy " was created by
 * ourselves. The name change must synchronize the @font - face at both ends. The rest are system fonts. When they are
 * not installed on the machine, the fallback behind the font stack will naturally fall back without error or blank.
 */
export const FONT_PRESETS: FontPreset[] = [
  {
    id: 'candy',
    stack:
      '"ShangshouSoftCandy","Yuanti SC","YouYuan","幼圆","Comic Sans MS","PingFang SC","Microsoft YaHei",sans-serif',
  },
  { id: 'yahei', stack: '"Microsoft YaHei","PingFang SC",sans-serif' },
  { id: 'youyuan', stack: '"YouYuan","Yuanti SC",sans-serif' },
  { id: 'kaiti', stack: '"KaiTi","STKaiti",serif' },
  { id: 'simsun', stack: '"SimSun","Songti SC",serif' },
  { id: 'comic', stack: '"Comic Sans MS","Comic Sans",cursive' },
  { id: 'system', stack: 'system-ui,sans-serif' },
];

/** The valid range of font sizes (px, including endpoints): the same conventions as host side fontValid - the setting page prompts accordingly, and the host intercepts manual changes accordingly. */
export const FONT_SIZE_MIN = 4;
export const FONT_SIZE_MAX = 200;

/**
 * font segment default value (consistent with the font segment of the built-in config.jsonc): 462 wide pet's bubble 21
 * px, and scales with pet size. Configurations without the font field are therefore still rendered with the existing
 * look and feel.
 */
export const DEFAULT_FONT: FontConfig = {
  family: 'candy',
  size: 21,
  followPet: true,
};

/** Press id to get the font stack; id is invalid or the first item in the fallback list (soft candy body) is missing, and the rendering layer no longer fallsback by itself. */
export function fontStackOf(id: string): string {
  return (FONT_PRESETS.find((p) => p.id === id) ?? FONT_PRESETS[0]).stack;
}

/** Base pet width (px): The anchor point for font size conversion, which is equal to the default size of the built-in configuration, and is also the design basis for the existing CSS coefficient. */
export const FONT_REF_SIZE = 462;

/** Bubble text size under reference width (px) = 0.0455 × 462 ≈ 21.02. */
export const BUBBLE_FONT_BASE_PX = 0.0455 * FONT_REF_SIZE;

/** The floating prompt font size under the reference width (px) = 0.026 × 462 ≈ 12.01. */
export const TIP_FONT_BASE_PX = 0.026 * FONT_REF_SIZE;

/**
 * The final font size of bubble and floating prompt (px), both ends share the same conversion to avoid drift. Font
 * size = base px × ( font.size ÷ default font size) × ( followPet ? pet width ÷ 462 : 1).
 * When followPet = false, it degenerates to a fixed font size of 462 width; if the configuration is modified by hand,
 * it will be processed according to the default conventions, and NaN or 0 will never be produced.
 * @param font - This pet's font configuration, missing DEFAULT_FONT.
 * @param size - The width of this pet px.
 */
export function resolveFontPx(font: FontConfig | undefined, size: number): { bubble: number; tip: number } {
  const own = Number(font?.size);
  // The ratio of the user layer font size to the default font size (default font size = DEFAULT_FONT.size)
  const ratio = Number.isFinite(own) && own > 0 ? own / DEFAULT_FONT.size : 1;
  const w = Number(size);
  const follow = font?.followPet !== false;
  const scale = follow && Number.isFinite(w) && w > 0 ? w / FONT_REF_SIZE : 1;
  return {
    bubble: BUBBLE_FONT_BASE_PX * ratio * scale,
    tip: TIP_FONT_BASE_PX * ratio * scale,
  };
}

/**
 * The ratio of the bottom edge of the bubble to the top edge of the pet box (corresponding to bottom of bubble CSS:
 * calc (100% - size ×0.108)). The protruded section is also included in the vertical space available for the bubble,
 * see bubbleTopMarginPx.
 */
export const BUBBLE_OVERLAP_RATIO = 0.108;

/**
 * bubble layout measurement (em, baseline = bubble text final font size --f). The coefficients have the same origin
 * as the CSS of dsh-pet-bubble and MEME_BUBBLE_CSS of shared/whisper.ts at both ends of the rendering layer. Changing
 * any CSS coefficient must be synchronized here, otherwise the upper margin of the desktop window will be too small
 * and the top of the bubble will be cut off by the window.
 */
export const BUBBLE_METRICS = {
  lineHeight: 1.6,
  padY: 0.4835,
  subScale: 0.7692,
  imgWidth: 7.4725,
  imgMargin: 0.3736,
  /** The upper limit of the image aspect ratio (the built-in assets/memes is all 128 wide and the height does not exceed 128) */
  imgMaxRatio: 1,
} as const;

/** The maximum height of the bubble (px): two lines of text (the main line of the balance bubble + the secondary line) plus a picture. The desktop side sets the top margin of the window accordingly. */
export function bubbleMaxHeightPx(font: FontConfig | undefined, size: number): number {
  const f = resolveFontPx(font, size).bubble;
  const m = BUBBLE_METRICS;
  return (
    m.padY * 2 * f + m.lineHeight * f + m.lineHeight * m.subScale * f + m.imgWidth * m.imgMaxRatio * f + m.imgMargin * f
  );
}

/**
 * The minimum top margin of the desktop window (px): at least the entire bubble must be accommodated. The bottom edge
 * of the bubble falls 0.108 × size below the top edge of the pet box, so the margin = the maximum height of the bubble
 * − this section. The default configuration (462 px pets / 21 px font size) is calculated as 195 px, which is still
 * less than the existing margin of 231 px, and the window size remains unchanged.
 */
export function bubbleTopMarginPx(font: FontConfig | undefined, size: number): number {
  const overlap = (Number(size) || 0) * BUBBLE_OVERLAP_RATIO;
  return Math.max(0, Math.ceil(bubbleMaxHeightPx(font, size) - overlap));
}
